-- Expand player creation origin/backstory choices.
-- Existing origins remain unchanged so current player identities keep their references.

ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name,
  tagline = EXCLUDED.tagline,
  description = EXCLUDED.description,
  icon = EXCLUDED.icon,
  starting_cash = EXCLUDED.starting_cash,
  starting_fame = EXCLUDED.starting_fame,
  skill_bonuses = EXCLUDED.skill_bonuses,
  reputation_modifiers = EXCLUDED.reputation_modifiers,
  display_order = EXCLUDED.display_order,
  is_active = true,
  updated_at = now();
